CREATE TYPE "PaymentStatus" AS ENUM ('pending', 'authorized', 'failed', 'refunded');
CREATE TYPE "WalletTransactionType" AS ENUM ('credit', 'debit', 'refund');
CREATE TABLE "wallets" ("id" UUID NOT NULL, "buyerId" UUID NOT NULL, "currency" VARCHAR(3) NOT NULL DEFAULT 'COP', "balance" DECIMAL(14,2) NOT NULL DEFAULT 0, "version" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "wallets_pkey" PRIMARY KEY ("id"));
CREATE TABLE "wallet_transactions" ("id" UUID NOT NULL, "walletId" UUID NOT NULL, "type" "WalletTransactionType" NOT NULL, "amount" DECIMAL(14,2) NOT NULL, "balanceAfter" DECIMAL(14,2) NOT NULL, "reason" VARCHAR(300) NOT NULL, "actorId" UUID, "idempotencyKey" VARCHAR(180), "paymentId" UUID, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "wallet_transactions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "payments" ("id" UUID NOT NULL, "orderId" UUID NOT NULL, "buyerId" UUID NOT NULL, "amount" DECIMAL(12,2) NOT NULL, "currency" VARCHAR(3) NOT NULL DEFAULT 'COP', "status" "PaymentStatus" NOT NULL DEFAULT 'pending', "idempotencyKey" VARCHAR(180), "failureReason" VARCHAR(300), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "payments_pkey" PRIMARY KEY ("id"));
CREATE TABLE "payment_outbox_events" ("id" UUID NOT NULL, "eventType" VARCHAR(120) NOT NULL, "aggregateId" UUID NOT NULL, "payload" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "publishedAt" TIMESTAMP(3), CONSTRAINT "payment_outbox_events_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "wallets_buyerId_key" ON "wallets"("buyerId"); CREATE UNIQUE INDEX "wallet_transactions_idempotencyKey_key" ON "wallet_transactions"("idempotencyKey"); CREATE INDEX "wallet_transactions_walletId_createdAt_idx" ON "wallet_transactions"("walletId", "createdAt"); CREATE UNIQUE INDEX "payments_orderId_key" ON "payments"("orderId"); CREATE UNIQUE INDEX "payments_idempotencyKey_key" ON "payments"("idempotencyKey"); CREATE INDEX "payments_buyerId_createdAt_idx" ON "payments"("buyerId", "createdAt"); CREATE INDEX "payment_outbox_events_publishedAt_createdAt_idx" ON "payment_outbox_events"("publishedAt", "createdAt");
ALTER TABLE "wallet_transactions" ADD CONSTRAINT "wallet_transactions_walletId_fkey" FOREIGN KEY ("walletId") REFERENCES "wallets"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
